// App version labels (CLAUDE.md "Phase III (part 2): App version").
//
// public/js/version.js is generated by scripts/write-version.mjs and gitignored,
// so it may simply not be there (a fresh clone, or a 404 in a test). The import
// is dynamic and every failure falls back to "dev": nothing here ever throws.

import { el } from './ui.js';
import { formatDayLong } from './logic.js';

const DEV = 'dev';

let promise = null;

function normalise(mod) {
  const pick = (value) => (typeof value === 'string' && value.trim() ? value.trim() : DEV);
  const version = pick(mod && mod.APP_VERSION);
  const build = pick(mod && mod.APP_BUILD);
  const rawDate = pick(mod && mod.APP_DATE);
  const date = rawDate === DEV ? DEV : (formatDayLong(rawDate) || rawDate);
  return {
    version,
    build,
    date,
    short: 'v' + version,
    line: `Version ${version} · build ${build} · updated ${date}`,
    title: `Version ${version}, build ${build}, updated ${date}`
  };
}

/** { version, build, date, short, line, title }. Always resolves. */
export function loadVersion() {
  if (!promise) {
    promise = import('./version.js').then(normalise).catch(() => normalise(null));
  }
  return promise;
}

/** The outlined pill that sits after the screen title in every dark header. */
export function createVersionPill() {
  const pill = el('span', {
    class: 'version-pill',
    testid: 'app-version',
    // role="note" so the aria-label is allowed: a bare <span>/<p> is a generic
    // element and naming it is prohibited (axe "aria-prohibited-attr").
    role: 'note',
    title: `Version ${DEV}, build ${DEV}, updated ${DEV}`,
    'aria-label': `Version ${DEV}, build ${DEV}, updated ${DEV}`,
    text: 'v' + DEV
  });
  loadVersion().then((v) => {
    pill.textContent = v.short;
    pill.setAttribute('title', v.title);
    pill.setAttribute('aria-label', v.title);
  });
  return pill;
}

/** The one-line footer on the login card. */
export function createVersionLine() {
  const line = el('p', {
    class: 'login__version',
    testid: 'login-version',
    role: 'note',
    title: `Version ${DEV}, build ${DEV}, updated ${DEV}`,
    'aria-label': `Version ${DEV}, build ${DEV}, updated ${DEV}`,
    text: `Version ${DEV} · build ${DEV} · updated ${DEV}`
  });
  loadVersion().then((v) => {
    line.textContent = v.line;
    line.setAttribute('title', v.title);
    line.setAttribute('aria-label', v.title);
  });
  return line;
}
